import { Component, inject, OnInit, signal } from '@angular/core';

import { EventsApiService } from '../../core/api/events-api.service';
import { EventSummary } from '../../core/api/event-summary';
import { EventCard } from './event-card/event-card';

@Component({
  selector: 'app-program-overview',
  imports: [EventCard],
  templateUrl: './program-overview.html',
  styleUrl: './program-overview.scss'
})
export class ProgramOverview implements OnInit {
  private readonly eventsApi = inject(EventsApiService);

  readonly events = signal<EventSummary[]>([]);

  ngOnInit(): void {
    this.eventsApi.getEvents().subscribe(events => this.events.set(events));
  }
}

@if (events().length > 0) {
