  });

  it('zeigt eine Fehlermeldung statt des Leer-Zustands, wenn der Service fehlschlägt', () => {
    configure({ getEvents: () => throwError(() => new Error('Netzwerkfehler')) });

    const fixture = TestBed.createComponent(ProgramOverview);
