(async () => {
  const browser = await chromium.launch();
  for (const [w,h,name] of [[1280,900,'desktop'],[375,800,'mobile']]) {
    const page = await browser.newPage({ viewport: { width: w, height: h } });
    await page.goto('http://localhost:4200/', { waitUntil: 'networkidle' });
    await page.screenshot({ path: '/tmp/overview-'+name+'.png', fullPage: true });
    await page.close();
  }
  await browser.close();
})();
